    StorageDescriptor sd = new StorageDescriptor(Collections.singletonList(schema), null, "org.apache.hadoop.mapred.TextInputFormat", "org.apache.hadoop.hive.ql.io.IgnoreKeyTextOutputFormat", false, 0, serde, null, null, new HashMap<String, String>());
    Table table = new Table(inputTable, "default", "me", 0, 0, 0, sd, null, new HashMap<String, String>(), null, null, TableType.MANAGED_TABLE.toString());
