    outputSchema = new HCatSchema(Arrays.asList(new HCatFieldSchema("word", HCatFieldSchema.Type.STRING, ""), new HCatFieldSchema("count", HCatFieldSchema.Type.INT, "")));
    // LATER Could I use HCatWriter here and the reader to read it?
    // Write some stuff into a file in the location of the table
