    out.writeChars("Mary had a little lamb\n");
    out.writeChars("its fleece was white as snow\n");
    out.writeChars("and everywhere that Mary went\n");
    out.writeChars("the lamb was sure to go\n");
    out.close();
    Map<String, String> env = new HashMap<>();
    env.put("HADOOP_CLASSPATH", System.getProperty(HCATCORE, ""));
    Map<String, String> results = HiveHelper.execCommand(new CommandLine("hive").addArgument("--service").addArgument("jar").addArgument(System.getProperty(JOBJAR)).addArgument(HCatalogMR.class.getName()).addArgument("-it").addArgument(inputTable).addArgument("-ot").addArgument(outputTable).addArgument("-is").addArgument(inputSchema.getSchemaAsTypeString()).addArgument("-os").addArgument(outputSchema.getSchemaAsTypeString()), env);
