// and hence different things will work here.
// This covers insert (non-partitioned, partitioned, dynamic partitions, overwrite, with
// values and select), and multi-insert.  Load is not tested as there's no guarantee that the
// test machine has access to HDFS and thus the ability to upload a file.
@Test
public void insert() throws SQLException {
    final String table1 = "bigtop_insert_table1";
    final String table2 = "bigtop_insert_table2";
    try (Statement stmt = conn.createStatement()) {
        stmt.execute("drop table if exists " + table1);
        stmt.execute("create table " + table1 + "(c1 tinyint," + " c2 smallint," + " c3 int," + " c4 bigint," + " c5 float," + " c6 double," + " c7 decimal(8,2)," + " c8 varchar(120)," + " c9 char(10)," + " c10 boolean)" + " partitioned by (p1 string)");
        // insert with partition
        stmt.execute("explain insert into " + table1 + " partition (p1 = 'a') values " + "(1, 2, 3, 4, 1.1, 2.2, 3.3, 'abcdef', 'ghi', true)," + "(5, 6, 7, 8, 9.9, 8.8, 7.7, 'jklmno', 'pqr', true)");
        stmt.execute("set hive.exec.dynamic.partition.mode=nonstrict");
        // dynamic partition
        stmt.execute("explain insert into " + table1 + " partition (p1) values " + "(1, 2, 3, 4, 1.1, 2.2, 3.3, 'abcdef', 'ghi', true, 'b')," + "(5, 6, 7, 8, 9.9, 8.8, 7.7, 'jklmno', 'pqr', true, 'b')");
        stmt.execute("drop table if exists " + table2);
        stmt.execute("create table " + table2 + "(c1 tinyint," + " c2 smallint," + " c3 int," + " c4 bigint," + " c5 float," + " c6 double," + " c7 decimal(8,2)," + " c8 varchar(120)," + " c9 char(10)," + " c10 boolean)");
        stmt.execute("explain insert into " + table2 + " values " + "(1, 2, 3, 4, 1.1, 2.2, 3.3, 'abcdef', 'ghi', true)," + "(5, 6, 7, 8, 9.9, 8.8, 7.7, 'jklmno', 'pqr', true)");
        stmt.execute("explain insert overwrite table " + table2 + " select c1, c2, c3, c4, c5, c6, " + "c7, c8, c9, c10 from " + table1);
        // multi-insert
        stmt.execute("from " + table1 + " insert into table " + table1 + " partition (p1 = 'c') " + " select c1, c2, c3, c4, c5, c6, c7, c8, c9, c10" + " insert into table " + table2 + " select c1, c2, c3, c4, c5, c6, c7, c8, c9, c10");
    }
}

