    Partition partition = new Partition(Collections.singletonList("x"), "default", tableName, 0, 0, sd, new HashMap<String, String>());
    client.add_partition(partition);
    List<Partition> partitions = new ArrayList<>(2);
    sd = new StorageDescriptor(Collections.singletonList(fs), null, conf.getVar(HiveConf.ConfVars.HIVEDEFAULTSERDE), conf.getVar(HiveConf.ConfVars.HIVEDEFAULTSERDE), false, 0, serde, null, null, new HashMap<String, String>());
    partitions.add(new Partition(Collections.singletonList("y"), "default", tableName, 0, 0, sd, new HashMap<String, String>()));
