@Test
public void testConcurrentScanAndPut() {
    String tableNameStr = Bytes.toString(tableName);
    System.out.println("Starting puts to test table " + tableNameStr);
    putSh.exec("(HBASE_CLASSPATH=. " + "hbase org.apache.bigtop.itest.hbase.system.Putter " + tableNameStr + " 13 -l " + putterLoops + " > /dev/null 2>&1 & echo $! ) 2> /dev/null");
    putter_pid = putSh.getOut().get(0);
    System.out.println("Starting concurrent scans of test table " + tableNameStr);
    scanSh.exec("HBASE_CLASSPATH=. hbase " + "org.apache.bigtop.itest.hbase.system.Scanner " + tableNameStr + " 13 -l " + scannerLoops + " 2>/dev/null");
    int splitRows = scanSh.getRet();
    System.out.println("Split rows: " + splitRows);
    assertTrue("Rows were split when scanning table with concurrent writes", splitRows == 0);
}

@Test
public void testLoadAndVerify() throws Exception {
    HTableDescriptor htd = HBaseTestUtil.createTestTableDescriptor(TEST_NAME, TEST_FAMILY);
    HBaseAdmin admin = HBaseTestUtil.getAdmin();
    assertNotNull("HBaseAdmin shouldn't be null", admin);
    int numPreCreate = 40;
    admin.createTable(htd, Bytes.toBytes(0L), Bytes.toBytes(-1L), numPreCreate);
    Configuration conf = HBaseConfiguration.create();
    doLoad(conf, htd);
    doVerify(conf, htd);
    // Only disable and drop if we succeeded to verify - otherwise it's useful
    // to leave it around for post-mortem
    deleteTable(admin, htd);
}

@Test
public void testRegionMover() throws InterruptedException {
    System.out.println("Beginning unloading and loading of region servers " + load_iterations + " times each");
    String cmd;
    for (int i = 0; i < load_iterations; i++) {
        for (String rs : regionservers) {
            // Unload
            cmd = unload_regionserver + rs;
            System.out.println(cmd);
            sh.exec(cmd);
            waitForNoRegionsInTransition();
            // Load
            cmd = load_regionserver + rs;
            System.out.println(cmd);
            sh.exec(cmd);
            waitForNoRegionsInTransition();
        }
    }
}
